//! The stance HUD as sprites and flat bands: which parts are drawn, where, and with which palette.
//!
//! The art lives in `assets/hud/sprites/stance_hud_art.rs`, generated by `showcase-vector/hudart`.
//! Every repeated part (a health cell, a gem) is one sprite drawn at a fixed step, and a colour
//! state (lit, empty, the other stance) is a different palette over the same texels, so two parts in
//! different states are the same pixels by construction. Axis-aligned areas are flat rectangles, so
//! nothing here depends on how the GPU fills a slanted triangle.
//!
//! A bar comes in a few sizes, each pixel art of its own and never scaled at run time (scaling would
//! break the identical cells). The bar in front is full size; the bar behind is a smaller size, as if
//! further back, and the sizes between are used for the frames while the bars trade places.
//!
//! The composition is written once against a `draw` callback, like `stance_hud_layout.rs`: the guest
//! turns each [`Op`] into a packet, the host viewer (`hudart`'s `hudview`) paints them into a frame.
//! This file has no dependencies, so both include it by path.

/// A rectangle of the atlas, in texels.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SpriteRect {
    pub u: u8,
    pub v: u8,
    pub w: u8,
    pub h: u8,
}

/// Rows `y0..y1` of a bar plate in one flat colour. A `glass` band is drawn semi-transparently
/// (average of the scene and the colour), so the scene shows through the well the cells sit in.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Band {
    pub y0: u8,
    pub y1: u8,
    pub rgb: [u8; 3],
    pub glass: bool,
}

/// One size of the bar. Columns are relative to the HUD column of the bar's origin (the left end
/// of every bar starts at `LCAP_X`), rows to the bar's first row.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SizeGeo {
    /// Distance between cells.
    pub pitch: i32,
    /// Left edge of the first cell's bottom row, and the row its top is on.
    pub cell_x0: i32,
    pub cell_row: i32,
    /// Rows of the bar.
    pub bar_h: i32,
    /// Left edge of the flat part of the plate and the first column of the right end.
    pub bar_x0: i32,
    pub cap_x: i32,
    /// Bands of the bar.
    pub band_count: usize,
    pub cell: SpriteRect,
    pub cap: SpriteRect,
    pub lcap: SpriteRect,
}

include!("../assets/hud/sprites/stance_hud_art.rs");

/// The two stances. Each has its own bar, which is a complete object: it can be drawn at any
/// position, in front or behind the other one, at any of its sizes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Stance {
    Horizon,
    Zenith,
}

impl Stance {
    /// Position in the per-stance arrays of [`HudState`] and in the generated tables.
    pub const fn index(self) -> usize {
        match self {
            Self::Horizon => 0,
            Self::Zenith => 1,
        }
    }

    /// The other stance.
    pub const fn other(self) -> Self {
        match self {
            Self::Horizon => Self::Zenith,
            Self::Zenith => Self::Horizon,
        }
    }
}

/// Frames the two bars take to trade places (at 30 frames a second, a quarter of a second).
pub const SWAP_FRAMES: u8 = 8;

/// How far the bars bow out sideways while they trade places, at the middle of the swap.
pub const SWAP_BOW: i32 = 6;

/// Everything the HUD shows; packets built from it stay valid while it is equal.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct HudState {
    /// The active stance: the bar in front, or the one coming to the front during a swap.
    pub stance: Stance,
    /// Lit health cells of each stance's bar, 0 to [`COUNT`].
    pub health: [u8; 2],
    /// Lit energy gems of each stance. The gems show the active stance's.
    pub energy: [u8; 2],
    /// 0 at rest. During a swap to `stance`, the frame of it, 1 to [`SWAP_FRAMES`] - 1.
    pub swap: u8,
}

/// One thing to paint, in screen pixels.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Op {
    /// A flat rectangle, semi-transparent when `glass`.
    Rect {
        x: i32,
        y: i32,
        w: i32,
        h: i32,
        rgb: [u8; 3],
        glass: bool,
    },
    /// A sprite from the atlas, drawn 1:1 with CLUT number `clut` of [`CLUTS`]. With `glass` the
    /// palette entries that carry the semi-transparency bit blend with the scene.
    Sprite {
        x: i32,
        y: i32,
        src: SpriteRect,
        clut: usize,
        glass: bool,
    },
    /// The GPU's mask bit: with `set` every pixel drawn from now on is marked, with `check` pixels
    /// that are marked are not drawn over. Both off ends the special case.
    Mask { set: bool, check: bool },
}

/// Ops one HUD needs at most: every band of both bars, both ends of both bars, both bars' cells,
/// the emblem, the gems and four mask changes.
pub const MAX_OPS: usize = 2 * BAND_MAX + 9 + 3 * (COUNT as usize);

/// Where a bar is, relative to the HUD's origin, and which size it is.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Pose {
    pub x: i32,
    pub y: i32,
    pub size: usize,
}

/// Which emblem palette to draw.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EmblemLook {
    Of(Stance),
    Halfway,
}

/// What a state looks like: the bars back to front, the emblem and the stance the gems follow.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Scene {
    pub behind: (Stance, Pose),
    pub front: (Stance, Pose),
    pub emblem: EmblemLook,
    pub gems: Stance,
}

/// Ease-out of frame `f` of a swap, 0 to 256: quicker at first, settling at the end. Halfway
/// between a straight line and a quadratic, so that even the last frames move by a pixel or more.
fn ease_out(f: u8) -> i32 {
    let u = f as i32 * 256 / SWAP_FRAMES as i32;
    let quadratic = 256 - (((256 - u) * (256 - u)) >> 8);
    (u + quadratic) >> 1
}

/// `a` to `b` by `p / 256`, rounded to a whole pixel.
fn lerp(a: i32, b: i32, p: i32) -> i32 {
    a + (((b - a) * p + 128) >> 8)
}

/// How far a bar bows out at progress `p`: 0 at both ends, [`SWAP_BOW`] in the middle.
fn bow(p: i32) -> i32 {
    (SWAP_BOW * ((4 * p * (256 - p)) >> 8)) >> 8
}

/// How many sizes a bar steps through at progress `p` of its way, 0 at the start, `BACK_SIZE` at the
/// end.
fn steps_at(p: i32) -> usize {
    ((p as usize) * (BACK_SIZE + 1) / 257).min(BACK_SIZE)
}

/// Top row of the bar behind.
const BACK_Y: i32 = FRONT_Y - LIFT + BACK_DROP;

/// The bars' poses and the draw order for `state`.
pub fn scene(state: &HudState) -> Scene {
    let front_pose = Pose {
        x: 0,
        y: FRONT_Y,
        size: 0,
    };
    let back_pose = Pose {
        x: BACK_X,
        y: BACK_Y,
        size: BACK_SIZE,
    };
    let (incoming, outgoing) = (state.stance, state.stance.other());
    if state.swap == 0 || state.swap >= SWAP_FRAMES {
        return Scene {
            behind: (outgoing, back_pose),
            front: (incoming, front_pose),
            emblem: EmblemLook::Of(incoming),
            gems: incoming,
        };
    }
    // The bar coming forward goes down and grows through the sizes, the one going back goes up and
    // shrinks, bowing out so that they pass each other, and the one coming forward is drawn in front
    // from the middle on.
    let p = ease_out(state.swap);
    let b = bow(p);
    let coming = Pose {
        x: lerp(BACK_X, 0, p) - b,
        y: lerp(BACK_Y, FRONT_Y, p),
        size: BACK_SIZE - steps_at(p),
    };
    let going = Pose {
        x: lerp(0, BACK_X, p) + b,
        y: lerp(FRONT_Y, BACK_Y, p),
        size: steps_at(p),
    };
    let first_half = p < 128;
    Scene {
        behind: if first_half {
            (incoming, coming)
        } else {
            (outgoing, going)
        },
        front: if first_half {
            (outgoing, going)
        } else {
            (incoming, coming)
        },
        emblem: if p < 100 {
            EmblemLook::Of(outgoing)
        } else if p < 150 {
            EmblemLook::Halfway
        } else {
            EmblemLook::Of(incoming)
        },
        gems: if first_half { outgoing } else { incoming },
    }
}

/// Which parts of a bar to paint.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Part {
    /// The translucent well and both ends, which carry translucent pixels.
    Glass,
    /// The opaque bands.
    Opaque,
    /// The well, the ends and the opaque bands: the plate without the cells.
    Plate,
    /// The cells.
    Cells,
}

/// The palette of a cell of the bar of `stance` at `size`, lit or empty. A cell packet only ever
/// changes between these two, so a health change is a one-word patch of the packet.
pub fn cell_clut(stance: Stance, size: usize, lit: bool) -> usize {
    stance.index() * CLUTS_PER_STANCE
        + size * CLUT_SIZE_STRIDE
        + if lit { CLUT_CELL_LIT } else { CLUT_CELL_EMPTY }
}

/// The palette of an energy gem, lit or empty.
pub fn gem_clut(lit: bool) -> usize {
    if lit {
        CLUT_GEM_LIT
    } else {
        CLUT_GEM_EMPTY
    }
}

/// Paint one complete bar of `stance`, `lit` cells lit, at `pose`.
pub fn bar(
    origin: (i32, i32),
    stance: Stance,
    pose: Pose,
    lit: u8,
    part: Part,
    draw: &mut impl FnMut(Op),
) {
    let (left, top) = (origin.0 + pose.x, origin.1 + pose.y);
    let s = stance.index();
    let geo = &GEO[pose.size];
    for band in &BANDS[s][pose.size][..geo.band_count] {
        let wanted = match part {
            Part::Plate => true,
            Part::Glass => band.glass,
            Part::Opaque => !band.glass,
            Part::Cells => false,
        };
        if wanted {
            draw(Op::Rect {
                x: left + geo.bar_x0,
                y: top + band.y0 as i32,
                w: geo.cap_x - geo.bar_x0,
                h: (band.y1 - band.y0) as i32,
                rgb: band.rgb,
                glass: band.glass,
            });
        }
    }
    let base = s * CLUTS_PER_STANCE + pose.size * CLUT_SIZE_STRIDE;
    if part == Part::Glass || part == Part::Plate {
        for (x, src) in [(LCAP_X, geo.lcap), (geo.cap_x, geo.cap)] {
            draw(Op::Sprite {
                x: left + x,
                y: top,
                src,
                clut: base + CLUT_CAP,
                glass: true,
            });
        }
    }
    if part == Part::Cells {
        for k in 0..COUNT {
            draw(Op::Sprite {
                x: left + geo.cell_x0 + geo.pitch * k,
                y: top + geo.cell_row,
                src: geo.cell,
                clut: cell_clut(stance, pose.size, (k as u8) < lit),
                glass: false,
            });
        }
    }
}

/// The ops that set the mask a given way.
pub const MASK_SET: Op = Op::Mask {
    set: true,
    check: false,
};
/// Set and check, for the cells of the bar behind.
pub const MASK_SET_CHECK: Op = Op::Mask {
    set: true,
    check: true,
};
/// Check only, for the plate of the bar behind.
pub const MASK_CHECK: Op = Op::Mask {
    set: false,
    check: true,
};
/// Neither: the opaque parts of the front bar.
pub const MASK_OFF: Op = Op::Mask {
    set: false,
    check: false,
};

/// The clut of the emblem for `look`.
pub fn emblem_clut(look: EmblemLook) -> usize {
    match look {
        EmblemLook::Of(s) => s.index() * CLUTS_PER_STANCE + CLUT_EMBLEM,
        EmblemLook::Halfway => CLUT_EMBLEM_HALFWAY,
    }
}

/// The emblem as one op, with its top-left at `origin`.
pub fn emblem_op(origin: (i32, i32), look: EmblemLook) -> Op {
    Op::Sprite {
        x: origin.0 + EMBLEM_X,
        y: origin.1 + EMBLEM_Y,
        src: SPRITE_EMBLEM,
        clut: emblem_clut(look),
        glass: false,
    }
}

/// Gem `k` as one op, lit or not, with the HUD's top-left at `origin`.
pub fn gem_op(origin: (i32, i32), k: i32, lit: bool) -> Op {
    Op::Sprite {
        x: origin.0 + GEM_X0 + GEM_PITCH * k,
        y: origin.1 + GEM_Y,
        src: SPRITE_GEM,
        clut: gem_clut(lit),
        glass: false,
    }
}

/// One complete bar on its own, at `origin`, at `size`: the same object the HUD composes, for
/// previews and tests.
pub fn bar_alone(
    origin: (i32, i32),
    stance: Stance,
    size: usize,
    lit: u8,
    draw: &mut impl FnMut(Op),
) {
    let pose = Pose { x: 0, y: 0, size };
    bar(origin, stance, pose, lit, Part::Plate, draw);
    bar(origin, stance, pose, lit, Part::Cells, draw);
}

/// Paint the HUD with its top-left at `origin`.
///
/// Painter's order, with a wrinkle. The wells are translucent, and the bar in front must hide the bar
/// behind it without letting it show through its well. So the translucent parts of the front bar
/// are painted first and mark the pixels they touch, the bar behind is painted next and skips
/// marked pixels, and the opaque parts of the front bar go on top. Any overlap of the two bars, at
/// any position, comes out the same way.
///
/// A translucent texel marks the pixel it lands on whether or not a mask was asked for (the GPU
/// keeps the texel's own bit 15). So the cells of the bar behind, which sit over its translucent
/// ends, are painted first, marking their pixels, and the plate of that bar follows and skips them.
pub fn compose(origin: (i32, i32), state: &HudState, draw: &mut impl FnMut(Op)) {
    let sc = scene(state);
    let lit = |s: Stance| state.health[s.index()];
    draw(MASK_SET);
    bar(
        origin,
        sc.front.0,
        sc.front.1,
        lit(sc.front.0),
        Part::Glass,
        draw,
    );
    draw(MASK_SET_CHECK);
    bar(
        origin,
        sc.behind.0,
        sc.behind.1,
        lit(sc.behind.0),
        Part::Cells,
        draw,
    );
    draw(MASK_CHECK);
    bar(
        origin,
        sc.behind.0,
        sc.behind.1,
        lit(sc.behind.0),
        Part::Plate,
        draw,
    );
    draw(MASK_OFF);
    bar(
        origin,
        sc.front.0,
        sc.front.1,
        lit(sc.front.0),
        Part::Opaque,
        draw,
    );
    bar(
        origin,
        sc.front.0,
        sc.front.1,
        lit(sc.front.0),
        Part::Cells,
        draw,
    );
    draw(emblem_op(origin, sc.emblem));
    let energy = state.energy[sc.gems.index()];
    for k in 0..COUNT {
        draw(gem_op(origin, k, (k as u8) < energy));
    }
}
